// Bundles the page side of the extension (extension/src/page/main.js and every module it
// imports) into ONE classic script, extension/src/page/bundle.js. Chrome refuses to load an
// extension module script from the YouTube page, but it does load a classic script.
//
// Usage (from the repo root): node scripts/build-page-bundle.mjs
//
// No dependencies. Only the module forms below are supported; anything else fails the build:
//   import { a, b as c } from './x.js';        import * as name from './x.js';
//   import './x.js';
//   export const name = ...;  (one plain declarator)   export function / async function / class
//   export { a, b as c };                        export { a, b as c } from './x.js';
// Specifiers must be relative ('./' or '../') and end in '.js'.
// Rejected: default imports and exports, export *, export let/var, dynamic import(), import.meta,
// import cycles, and assignments to an exported binding (the bundle copies exports once, after
// the module has run, so a later reassignment would not reach the importers).
//
// Each module runs in its own function scope, so top-level names of different modules never
// collide and nothing is renamed. Imports become `const { a, b: c } = bundledModuleNExports;`
// at the top of the importing module's scope.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const BUNDLE_HEADER = '// Generated by scripts/build-page-bundle.mjs. Do not edit by hand.';

const EXTENSION_ROOT = fileURLToPath(new URL('../extension/', import.meta.url));
const PAGE_ENTRY_FILE = resolve(EXTENSION_ROOT, 'src/page/main.js');
const PAGE_BUNDLE_FILE = resolve(EXTENSION_ROOT, 'src/page/bundle.js');

class BundleError extends Error {
  constructor(message) {
    super(`build-page-bundle: ${message}`);
    this.name = 'BundleError';
  }
}

// ---------------------------------------------------------------------------
// Tokenizer: enough of JavaScript to find real `import`/`export` keywords and identifiers,
// skipping comments, strings, template literals and regular expression literals.
// ---------------------------------------------------------------------------

const IDENTIFIER_PATTERN = /[\p{ID_Start}$_][\p{ID_Continue}$‌‍]*/uy;
const NUMBER_PATTERN = /(?:\d|\.\d)[\w.]*/y;
const KEYWORDS_BEFORE_EXPRESSION = new Set([
  'return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw',
  'case', 'do', 'else', 'yield', 'await',
]);

/**
 * @typedef {{type: 'identifier'|'punctuator'|'string'|'template'|'regex'|'number',
 *   value: string, start: number, end: number}} Token
 */

/** @returns {Token[]} */
function tokenize(text, describeLocation) {
  const tokens = [];
  let position = 0;

  function fail(message, at) {
    throw new BundleError(`${describeLocation(at)}: ${message}`);
  }

  function slashStartsRegex() {
    const previous = tokens.at(-1);
    if (!previous) return true;
    if (previous.type === 'punctuator') return ![')', ']', '}'].includes(previous.value);
    if (previous.type === 'identifier') return KEYWORDS_BEFORE_EXPRESSION.has(previous.value);
    return false;
  }

  function skipQuoted(start, quote) {
    let index = start + 1;
    while (index < text.length) {
      const character = text[index];
      if (character === '\\') index += 2;
      else if (character === quote) return index + 1;
      else if (character === '\n') fail('unterminated string literal', start);
      else index += 1;
    }
    return fail('unterminated string literal', start);
  }

  function skipRegex(start) {
    let index = start + 1;
    let inClass = false;
    while (index < text.length) {
      const character = text[index];
      if (character === '\\') index += 2;
      else if (character === '\n') fail('unterminated regular expression', start);
      else {
        if (character === '[') inClass = true;
        else if (character === ']') inClass = false;
        else if (character === '/' && !inClass) {
          index += 1;
          while (index < text.length && /[a-z]/i.test(text[index])) index += 1;
          return index;
        }
        index += 1;
      }
    }
    return fail('unterminated regular expression', start);
  }

  /** Scans template text from `start` (just after '`' or '}') to the closing '`' or a '${'. */
  function scanTemplateChunk(start) {
    let index = start;
    while (index < text.length) {
      const character = text[index];
      if (character === '\\') index += 2;
      else if (character === '`') return { end: index + 1, opensSubstitution: false };
      else if (character === '$' && text[index + 1] === '{') return { end: index + 2, opensSubstitution: true };
      else index += 1;
    }
    return fail('unterminated template literal', start);
  }

  // Each entry is either 'brace' (a plain `{`) or 'template' (a `${` inside a template).
  const braceStack = [];

  function pushTemplateChunk(start, contentStart) {
    const chunk = scanTemplateChunk(contentStart);
    tokens.push({ type: 'template', value: text.slice(start, chunk.end), start, end: chunk.end });
    if (chunk.opensSubstitution) braceStack.push('template');
    return chunk.end;
  }

  while (position < text.length) {
    const character = text[position];
    if (/\s/.test(character)) {
      position += 1;
    } else if (character === '/' && text[position + 1] === '/') {
      const lineEnd = text.indexOf('\n', position);
      position = lineEnd === -1 ? text.length : lineEnd;
    } else if (character === '/' && text[position + 1] === '*') {
      const commentEnd = text.indexOf('*/', position + 2);
      if (commentEnd === -1) fail('unterminated block comment', position);
      position = commentEnd + 2;
    } else if (character === '"' || character === "'") {
      const end = skipQuoted(position, character);
      tokens.push({ type: 'string', value: text.slice(position, end), start: position, end });
      position = end;
    } else if (character === '`') {
      position = pushTemplateChunk(position, position + 1);
    } else if (character === '}' && braceStack.at(-1) === 'template') {
      braceStack.pop();
      position = pushTemplateChunk(position, position + 1);
    } else if (character === '/' && slashStartsRegex()) {
      const end = skipRegex(position);
      tokens.push({ type: 'regex', value: text.slice(position, end), start: position, end });
      position = end;
    } else {
      IDENTIFIER_PATTERN.lastIndex = position;
      NUMBER_PATTERN.lastIndex = position;
      const identifier = IDENTIFIER_PATTERN.exec(text);
      const number = identifier ? null : NUMBER_PATTERN.exec(text);
      if (identifier) {
        tokens.push({ type: 'identifier', value: identifier[0], start: position, end: position + identifier[0].length });
        position += identifier[0].length;
      } else if (number) {
        tokens.push({ type: 'number', value: number[0], start: position, end: position + number[0].length });
        position += number[0].length;
      } else {
        if (character === '{') braceStack.push('brace');
        if (character === '}') braceStack.pop();
        tokens.push({ type: 'punctuator', value: character, start: position, end: position + 1 });
        position += 1;
      }
    }
  }
  return tokens;
}

// ---------------------------------------------------------------------------
// Module reading: finds import and export statements and checks they are supported.
// ---------------------------------------------------------------------------

/**
 * @typedef {{
 *   filePath: string, moduleId: string, text: string, tokens: Token[],
 *   removals: {start: number, end: number}[],
 *   imports: {sourceFile: string, bindings: {imported: string, local: string}[], namespaceLocal: string|null}[],
 *   exports: Map<string, {local: string}|{sourceFile: string, imported: string}>,
 *   localExportDeclarations: Map<string, Token>,
 * }} ModuleRecord
 */

function lineOfOffset(text, offset) {
  let line = 1;
  for (let index = 0; index < offset && index < text.length; index += 1) if (text[index] === '\n') line += 1;
  return line;
}

/** @returns {ModuleRecord} */
function readModule(filePath, sourceRoot) {
  const moduleId = relative(sourceRoot, filePath).split(sep).join('/');
  let text;
  try {
    text = readFileSync(filePath, 'utf8').replace(/\r\n/g, '\n');
  } catch {
    throw new BundleError(`cannot read module ${moduleId}`);
  }
  const describeLocation = (offset) => `${moduleId}:${lineOfOffset(text, offset)}`;
  const tokens = tokenize(text, describeLocation);
  /** @type {ModuleRecord} */
  const record = {
    filePath, moduleId, text, tokens, removals: [], imports: [], exports: new Map(), localExportDeclarations: new Map(),
  };

  function fail(message, token) {
    throw new BundleError(`${describeLocation(token?.start ?? text.length)}: ${message}`);
  }

  function tokenAt(index) {
    return tokens[index] ?? fail('unexpected end of module');
  }

  function expectPunctuator(index, value) {
    const token = tokenAt(index);
    if (token.type !== 'punctuator' || token.value !== value) fail(`expected '${value}' but found '${token.value}'`, token);
  }

  function expectIdentifier(index, what) {
    const token = tokenAt(index);
    if (token.type !== 'identifier') fail(`expected ${what} but found '${token.value}'`, token);
    return token.value;
  }

  function isWord(index, value) {
    const token = tokens[index];
    return token?.type === 'identifier' && token.value === value;
  }

  function isPunctuator(index, value) {
    const token = tokens[index];
    return token?.type === 'punctuator' && token.value === value;
  }

  function resolveSpecifier(index) {
    const token = tokenAt(index);
    if (token.type !== 'string') fail(`expected a module specifier string but found '${token.value}'`, token);
    const specifier = token.value.slice(1, -1);
    if (specifier.includes('\\')) fail(`escape sequences in specifier ${token.value} are not supported`, token);
    if (!specifier.startsWith('./') && !specifier.startsWith('../')) fail(`bare specifier '${specifier}' is not supported`, token);
    if (!specifier.endsWith('.js')) fail(`specifier '${specifier}' must end in '.js'`, token);
    const sourceFile = resolve(dirname(filePath), specifier);
    const fromRoot = relative(sourceRoot, sourceFile);
    if (fromRoot.startsWith('..')) fail(`specifier '${specifier}' points outside the source root`, token);
    return sourceFile;
  }

  /** Parses `{ a, b as c }` starting at the '{'. Returns the pairs and the index after '}'. */
  function parseNameList(index) {
    expectPunctuator(index, '{');
    const pairs = [];
    let cursor = index + 1;
    while (!isPunctuator(cursor, '}')) {
      const name = expectIdentifier(cursor, 'a binding name');
      cursor += 1;
      let alias = name;
      if (isWord(cursor, 'as')) {
        alias = expectIdentifier(cursor + 1, 'a name after as');
        cursor += 2;
      }
      if (name === 'default' || alias === 'default') fail('default imports and exports are not supported', tokens[cursor - 1]);
      pairs.push({ name, alias });
      if (isPunctuator(cursor, ',')) cursor += 1;
      else if (!isPunctuator(cursor, '}')) fail(`expected ',' or '}' but found '${tokenAt(cursor).value}'`, tokens[cursor]);
    }
    return { pairs, nextIndex: cursor + 1 };
  }

  /** Ends a statement at `index` (optional ';') and returns the text offset after it. */
  function statementEnd(index) {
    if (isWord(index, 'with') || isWord(index, 'assert')) fail('import attributes are not supported', tokens[index]);
    return isPunctuator(index, ';') ? tokens[index].end : tokens[index - 1].end;
  }

  /** Removes a whole statement; also takes the rest of its line when only whitespace remains. */
  function removeStatement(start, end) {
    const lineEnd = text.indexOf('\n', end);
    const restOfLine = text.slice(end, lineEnd === -1 ? text.length : lineEnd);
    const removalEnd = /^\s*$/.test(restOfLine) ? (lineEnd === -1 ? text.length : lineEnd + 1) : end;
    record.removals.push({ start, end: removalEnd });
  }

  function addExport(exportedName, binding, token) {
    if (record.exports.has(exportedName)) fail(`'${exportedName}' is exported twice`, token);
    record.exports.set(exportedName, binding);
  }

  function parseImport(index) {
    const keyword = tokens[index];
    let cursor = index + 1;
    if (tokenAt(cursor).type === 'string') {
      record.imports.push({ sourceFile: resolveSpecifier(cursor), bindings: [], namespaceLocal: null });
      removeStatement(keyword.start, statementEnd(cursor + 1));
      return;
    }
    let bindings = [];
    let namespaceLocal = null;
    if (isPunctuator(cursor, '{')) {
      const list = parseNameList(cursor);
      bindings = list.pairs.map(({ name, alias }) => ({ imported: name, local: alias }));
      cursor = list.nextIndex;
    } else if (isPunctuator(cursor, '*')) {
      if (!isWord(cursor + 1, 'as')) fail("expected 'as' after 'import *'", tokens[cursor + 1]);
      namespaceLocal = expectIdentifier(cursor + 2, 'a namespace name');
      cursor += 3;
    } else {
      fail(`unsupported import form 'import ${tokenAt(cursor).value}' (default imports are not supported)`, tokens[cursor]);
    }
    if (!isWord(cursor, 'from')) fail(`expected 'from' but found '${tokenAt(cursor).value}'`, tokens[cursor]);
    record.imports.push({ sourceFile: resolveSpecifier(cursor + 1), bindings, namespaceLocal });
    removeStatement(keyword.start, statementEnd(cursor + 2));
  }

  /** Requires `export const name = ...;` with one declarator, ended by ';' at its own depth. */
  function checkSingleDeclarator(index) {
    let depth = 0;
    for (let cursor = index; cursor < tokens.length; cursor += 1) {
      const token = tokens[cursor];
      if (token.type !== 'punctuator') continue;
      if ('{(['.includes(token.value)) depth += 1;
      else if ('})]'.includes(token.value)) depth -= 1;
      else if (depth === 0 && token.value === ',') fail('export const with several declarators is not supported', token);
      else if (depth === 0 && token.value === ';') return;
    }
    fail("export const must end with ';'", tokens[index]);
  }

  function parseExport(index) {
    const keyword = tokens[index];
    const next = tokenAt(index + 1);
    const removeKeywordOnly = () => record.removals.push({ start: keyword.start, end: next.start });
    const declare = (nameIndex) => {
      const name = expectIdentifier(nameIndex, 'a declaration name');
      addExport(name, { local: name }, tokens[nameIndex]);
      record.localExportDeclarations.set(name, tokens[nameIndex]);
      removeKeywordOnly();
    };

    if (isWord(index + 1, 'const')) {
      if (tokenAt(index + 2).type !== 'identifier') fail('destructuring in export const is not supported', tokens[index + 2]);
      expectPunctuator(index + 3, '=');
      checkSingleDeclarator(index + 4);
      declare(index + 2);
    } else if (isWord(index + 1, 'let') || isWord(index + 1, 'var')) {
      fail(`export ${next.value} is not supported (exports are copied once; use export const)`, next);
    } else if (isWord(index + 1, 'function')) {
      declare(isPunctuator(index + 2, '*') ? index + 3 : index + 2);
    } else if (isWord(index + 1, 'async') && isWord(index + 2, 'function')) {
      declare(isPunctuator(index + 3, '*') ? index + 4 : index + 3);
    } else if (isWord(index + 1, 'class')) {
      declare(index + 2);
    } else if (isPunctuator(index + 1, '{')) {
      const list = parseNameList(index + 1);
      let cursor = list.nextIndex;
      if (isWord(cursor, 'from')) {
        const sourceFile = resolveSpecifier(cursor + 1);
        record.imports.push({ sourceFile, bindings: [], namespaceLocal: null });
        for (const { name, alias } of list.pairs) addExport(alias, { sourceFile, imported: name }, keyword);
        cursor += 2;
      } else {
        for (const { name, alias } of list.pairs) addExport(alias, { local: name }, keyword);
      }
      removeStatement(keyword.start, statementEnd(cursor));
    } else {
      fail(`unsupported export form 'export ${next.value}'`, next);
    }
  }

  let depth = 0;
  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];
    if (token.type === 'punctuator') {
      if ('{(['.includes(token.value)) depth += 1;
      else if ('})]'.includes(token.value)) depth -= 1;
      continue;
    }
    if (token.type !== 'identifier' || (token.value !== 'import' && token.value !== 'export')) continue;
    if (isPunctuator(index - 1, '.')) continue; // a property such as `object.import`
    if (token.value === 'import' && isPunctuator(index + 1, '(')) fail('dynamic import() is not supported', token);
    if (token.value === 'import' && isPunctuator(index + 1, '.')) fail('import.meta is not supported in the page bundle', token);
    if (depth !== 0) {
      if (isPunctuator(index + 1, ':')) continue; // an object key such as `{ import: 1 }`
      fail(`'${token.value}' is only supported at the top level of a module`, token);
    }
    if (token.value === 'import') parseImport(index);
    else parseExport(index);
  }
  if (depth !== 0) fail('unbalanced brackets');

  checkNoReassignedExports(record, fail);
  return record;
}

/** Fails when code assigns to an exported local binding (the bundle copies exports once). */
function checkNoReassignedExports(record, fail) {
  const { tokens } = record;
  const exportedLocals = new Set(
    [...record.exports.values()].filter((binding) => 'local' in binding).map((binding) => binding.local),
  );
  // Single-character punctuator tokens that touch each other form one operator, e.g. '+' '=' is '+='.
  function operatorTextAfter(index) {
    let operatorText = '';
    for (let cursor = index + 1; tokens[cursor]?.type === 'punctuator'; cursor += 1) {
      if (cursor > index + 1 && tokens[cursor - 1].end !== tokens[cursor].start) break;
      operatorText += tokens[cursor].value;
    }
    return operatorText;
  }
  function operatorTextBefore(index) {
    let operatorText = '';
    for (let cursor = index - 1; tokens[cursor]?.type === 'punctuator'; cursor -= 1) {
      if (cursor < index - 1 && tokens[cursor].end !== tokens[cursor + 1].start) break;
      operatorText = tokens[cursor].value + operatorText;
    }
    return operatorText;
  }
  const ASSIGNMENT_AFTER = /^(>>>=|<<=|>>=|\*\*=|&&=|\|\|=|\?\?=|[+\-*/%&|^]=|=(?![=>])|\+\+|--)/;
  const INCREMENT_BEFORE = /(\+\+|--)$/;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];
    if (token.type !== 'identifier' || !exportedLocals.has(token.value)) continue;
    if (record.localExportDeclarations.get(token.value) === token) continue;
    if (tokens[index - 1]?.type === 'punctuator' && tokens[index - 1].value === '.') continue;
    if (ASSIGNMENT_AFTER.test(operatorTextAfter(index)) || INCREMENT_BEFORE.test(operatorTextBefore(index))) {
      fail(`exported binding '${token.value}' is reassigned; the bundle copies exports once, so this is not supported`, token);
    }
  }
}

// ---------------------------------------------------------------------------
// Bundle assembly.
// ---------------------------------------------------------------------------

function exportsBindingName(moduleIndex) {
  return `bundledModule${moduleIndex}Exports`;
}

/** Loads the module graph and returns the records in dependency order (entry last). */
function loadModulesInDependencyOrder(entryFile, sourceRoot) {
  const records = new Map();
  const ordered = [];
  const inProgress = [];

  function visit(filePath) {
    if (records.has(filePath)) {
      if (inProgress.includes(filePath)) {
        const cycle = [...inProgress.slice(inProgress.indexOf(filePath)), filePath].map((path) => records.get(path).moduleId);
        throw new BundleError(`import cycle is not supported: ${cycle.join(' -> ')}`);
      }
      return;
    }
    const record = readModule(filePath, sourceRoot);
    records.set(filePath, record);
    inProgress.push(filePath);
    for (const { sourceFile } of record.imports) visit(sourceFile);
    inProgress.pop();
    ordered.push(record);
  }

  visit(resolve(entryFile));
  return ordered;
}

function bodyWithoutModuleSyntax(record) {
  const removals = [...record.removals].sort((left, right) => left.start - right.start);
  let body = '';
  let position = 0;
  for (const { start, end } of removals) {
    body += record.text.slice(position, start);
    position = end;
  }
  body += record.text.slice(position);
  return body.replace(/^\n+/, '').replace(/\s+$/, '');
}

/**
 * Bundles `entryFile` and the modules it imports into one classic script.
 * @param {{entryFile: string, sourceRoot: string}} options
 * @returns {string} the bundle text with LF line endings
 */
export function buildBundle({ entryFile, sourceRoot }) {
  const records = loadModulesInDependencyOrder(entryFile, sourceRoot);
  const indexByFile = new Map(records.map((record, index) => [record.filePath, index]));

  // The only names the bundle adds; fail if any module already uses one of them.
  const generatedNames = new Set(records.map((_, index) => exportsBindingName(index)));
  for (const record of records) {
    const clash = record.tokens.find((token) => token.type === 'identifier' && generatedNames.has(token.value));
    if (clash) {
      throw new BundleError(
        `${record.moduleId}:${lineOfOffset(record.text, clash.start)}: identifier '${clash.value}' collides with a name the bundle generates`,
      );
    }
  }

  function exportedNamesOf(sourceFile) {
    return records[indexByFile.get(sourceFile)].exports;
  }

  const sections = [];
  records.forEach((record, index) => {
    const isEntry = index === records.length - 1;
    const importLines = [];
    for (const { sourceFile, bindings, namespaceLocal } of record.imports) {
      const sourceBinding = exportsBindingName(indexByFile.get(sourceFile));
      const sourceExports = exportedNamesOf(sourceFile);
      for (const { imported } of bindings) {
        if (!sourceExports.has(imported)) {
          throw new BundleError(`${record.moduleId}: imports '${imported}', which ${records[indexByFile.get(sourceFile)].moduleId} does not export`);
        }
      }
      if (namespaceLocal) importLines.push(`const ${namespaceLocal} = ${sourceBinding};`);
      if (bindings.length > 0) {
        const parts = bindings.map(({ imported, local }) => (imported === local ? imported : `${imported}: ${local}`));
        importLines.push(`const { ${parts.join(', ')} } = ${sourceBinding};`);
      }
    }

    const exportEntries = [];
    for (const [exportedName, binding] of record.exports) {
      if ('local' in binding) {
        exportEntries.push(`${exportedName}: ${binding.local}`);
      } else {
        if (!exportedNamesOf(binding.sourceFile).has(binding.imported)) {
          throw new BundleError(
            `${record.moduleId}: re-exports '${binding.imported}', which ${records[indexByFile.get(binding.sourceFile)].moduleId} does not export`,
          );
        }
        exportEntries.push(`${exportedName}: ${exportsBindingName(indexByFile.get(binding.sourceFile))}.${binding.imported}`);
      }
    }

    const lines = [`// Module: ${record.moduleId}${isEntry ? ' (entry)' : ''}`];
    lines.push(isEntry ? '(function () {' : `const ${exportsBindingName(index)} = (function () {`);
    lines.push(...importLines);
    const body = bodyWithoutModuleSyntax(record);
    if (body) lines.push(body);
    if (!isEntry) lines.push(`return Object.freeze({ ${exportEntries.join(', ')} });`);
    lines.push('})();');
    sections.push(lines.join('\n'));
  });

  const entryId = records.at(-1).moduleId;
  return [
    BUNDLE_HEADER,
    `// Entry: ${entryId}. Rebuild with: node scripts/build-page-bundle.mjs`,
    '(function () {',
    "'use strict';",
    '',
    sections.join('\n\n'),
    '})();',
    '',
  ].join('\n');
}

/** Builds the page bundle from extension/src/page/main.js. */
export function buildPageBundle() {
  return buildBundle({ entryFile: PAGE_ENTRY_FILE, sourceRoot: EXTENSION_ROOT });
}

const runAsScript = process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url;
if (runAsScript) {
  writeFileSync(PAGE_BUNDLE_FILE, buildPageBundle());
  console.log(`build-page-bundle: wrote ${relative(process.cwd(), PAGE_BUNDLE_FILE)}`);
}
